              </div>
              <div style={{ flex: 1 }}>
                <ChatWindow myUid={currentUser.uid} otherUid={activeChatStudent?.id} otherName={activeChatStudent?.name} myName={userProfile.name} otherEmail={activeChatStudent?.email} />
